window.RP_SESSION={"id":"S-cd07bac63853","messages":[{"id":"RP-0122032","time":"2026-04-20T04:06:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]},{"id":"RP-0122033","time":"2026-04-20T08:51:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"읏차...\"\n\n손도끼로 장작을 패는 티아멧. 내려칠 때마다 불타는 손도끼에서 불꽃이 튑니다.","characters":["P-22fdf8486544"]},{"id":"RP-0122034","time":"2026-04-20T08:52:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"그나저나 장작이 거의 다 떨어졌군요. 나무를 하러 가야 할 것 같습니다.","characters":["P-22fdf8486544"]},{"id":"RP-0122035","time":"2026-04-20T08:56:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"가볼까.\"\n\n손도끼를 들고 숲으로 향합니다.","characters":["P-22fdf8486544"]},{"id":"RP-0122036","time":"2026-04-20T10:03:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c2ae9261373e"]},{"id":"RP-0122037","time":"2026-04-20T10:03:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]},{"id":"RP-0122038","time":"2026-04-20T10:04:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-c2ae9261373e"]},{"id":"RP-0122039","time":"2026-04-20T10:04:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'라쿠나'의 민첩 판정 :\n[2] + [2] = [4]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0122040","time":"2026-04-20T10:05:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"우엑-\"\n\n 나무에서 떨어진 라쿠나","characters":["P-c2ae9261373e"]},{"id":"RP-0122041","time":"2026-04-20T10:05:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-c2ae9261373e"]},{"id":"RP-0122042","time":"2026-04-20T10:05:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'라쿠나'의 체력 판정 :\n[7] + [1] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0122043","time":"2026-04-20T10:06:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"아파~\"\n\n 다행히 크게 다치진 않았네요","characters":["P-c2ae9261373e"]},{"id":"RP-0122044","time":"2026-04-20T10:16:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"뭐야 넌\"\n\n나무를 하고 있던 티아멧. 갑자기 나무에서 사람이 떨어지니 놀란 눈치입니다.","characters":["P-22fdf8486544"]},{"id":"RP-0122045","time":"2026-04-20T10:20:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"뭐야 넌?\"\n\n 엉덩이를 툭툭 털며 일어난다\n\n\"내 이름, 라쿠나!\"","characters":["P-c2ae9261373e"]},{"id":"RP-0122046","time":"2026-04-20T10:20:00+09:00","room":"RP","name":"샤를로타 롯테","profile":"샤를로타 롯테","identity":"unresolved","type":"dialogue","body":"스쿠나","characters":[]},{"id":"RP-0122047","time":"2026-04-20T10:25:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"...난 티아멧.\"\n\n신기한 놈이라고 생각하고는, 다시 돌아서 나무를 도끼로 자르기 시작합니다.","characters":["P-22fdf8486544"]},{"id":"RP-0122048","time":"2026-04-20T10:26:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"티아멧, 친구!\"\n\n 그가 도끼질을 하는 모습을 빤히ㅡ 구경합니다","characters":["P-c2ae9261373e"]},{"id":"RP-0122049","time":"2026-04-20T10:27:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"읏차...\"\n\n거의 다 베어낸 나무 밑동에 그을음이 잔뜩 묻습니다. 줄기에 발을 얹고 힘주어 밀자 우지직ㅡ 하며 나무가 넘어갑니다.","characters":["P-22fdf8486544"]},{"id":"RP-0122050","time":"2026-04-20T10:28:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"오오!\"\n\n 나무가 넘어가는 모습에 박수를 칩니다","characters":["P-c2ae9261373e"]},{"id":"RP-0122051","time":"2026-04-20T10:28:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"나도, 읏차!\"\n\n 그에게 손을 뻗어 뭔갈 요구합니댜","characters":["P-c2ae9261373e"]},{"id":"RP-0122052","time":"2026-04-20T10:32:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"?\"\n\n그가 손을 뻗자, 무슨 의도인지 이해를 못한 채 갸웃하고는 쓰러진 나무를 자르러 갑니다.","characters":["P-22fdf8486544"]},{"id":"RP-0122053","time":"2026-04-20T10:34:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"나도!\"\n\n 그를 졸졸 따라가네요","characters":["P-c2ae9261373e"]},{"id":"RP-0122054","time":"2026-04-20T10:38:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"콰직, 콰직...\n\n불타는 손도끼를 내리칠 때마다 불똥이 튀며 두꺼운 나무가 천천히 잘려나갑니다.","characters":["P-22fdf8486544"]},{"id":"RP-0122055","time":"2026-04-20T13:56:00+09:00","room":"RP","name":"샤를로타 롯테","profile":"샤를로타 롯테","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-0122056","time":"2026-04-20T13:56:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]},{"id":"RP-0122057","time":"2026-04-20T13:56:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"unresolved","type":"dialogue","body":"뭣.","characters":[]},{"id":"RP-0122058","time":"2026-04-20T13:56:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"unresolved","type":"dialogue","body":"다시 장작 패~","characters":[]}]};
